def digest(data):
    return hashlib.sha256(data).hexdigest()


def checked_inputs():
    raw = (REPO/MANIFEST_PATH).read_bytes()
    assert digest(raw) == MANIFEST_SHA, 'input manifest identity'
    manifest = json.loads(raw)
    assert manifest['schema'] == 'installed-background-inputs-v1'
    members = manifest['members']
    assert len(AUDIT_INPUT_PATHS) == len(set(AUDIT_INPUT_PATHS))
    assert set(AUDIT_INPUT_PATHS) == set(members) | {MANIFEST_PATH}, 'declared input coverage'
    data = {}
    for path, row in members.items():
        assert not Path(path).is_absolute() and '..' not in Path(path).parts
        b = (REPO/path).read_bytes()
        assert len(b) == row['bytes'] and digest(b) == row['sha256'], 'input identity: '+path
        data[path] = b
    index = json.loads(data[PACKET+'/SOURCE_INDEX.json'])
    originals = {}
    for alias, row in index['originals'].items():
        b = gzip.decompress(data[row['stored_path']])
        assert len(b) == row['bytes'] and digest(b) == row['sha256'], 'decoded original: '+alias
        originals[alias] = b
    body_map = json.loads(data[PACKET+'/BODY_MAP.json'])
    assert len(body_map['complete_proofs']) == 4
    for row in body_map['complete_proofs']:
        raw = originals[row['alias']]
        assert len(raw) == row['bytes'] and digest(raw) == row['sha256']
        assert data[NOTE][row['start']:row['end']] == raw and data[NOTE].count(raw) == 1, 'complete proof interval'
    binding = json.loads(data[PACKET+'/BINDING.json'])
    for row in binding['exact_parent_clauses']:
        raw = originals[row['alias']]
        parent = data[row['canonical_path']]
        assert parent[row['start']:row['end']] == raw and parent.count(raw) == 1, 'parent clause'
    assert binding['science_head'] == '7fa2d130984e52fdac74fc4523278e591bad667f'
    return data, originals


def main():
    data, originals = checked_inputs()
    print(json.dumps({'result':'analytic_source_binding_completed',
        'decoded_originals':len(originals), 'complete_proofs':4,
        'scientific_programs_run':0, 'computed_recurrence_certificates':0,
        'scope':'Identity/interval verification only. Analytic derivations and selective checks are archived evidence; this runner does not prove their mathematics.',
        'limits':'Supplied finite carrier, K data, control, purity, timing, calibration and reader contracts. No native realization, practical recurrence or retained audit.'},sort_keys=True))
    print('per_element: supplied full coherent or complete-output error contracts')
    print('per_site: literal ordinary-neighbor gates and explicit eligible identity extension')
    print('per_mode: no physical energy or continuum-mode identification')
    print('per_block: full reference and both binary outcomes; actual success normalization')
    print('lattice_wide: sufficient finite-M family resources; complete recurrence wait charged')


if __name__ == '__main__':
    main()
